/**
 * 健康工作台 · 菜谱静态数据
 *
 * 来源：二十一篇公众号家常菜合集（20 道荤菜 + 6 道下饭小炒 + 8 道白菜做法 + 20 道鱼虾豆腐 + 20 道素菜 + 20 道凉菜主食
 *      + 16 道虾 + 8 道素菜 + 10 道鱼肉 + 10 道鱼片 + 40 道羊肉
 *      + 26 道牛肉 + 14 道炖肉 + 40 道客家菜 + 8 道虾 + 10 道茄子 + 40 道鸡蛋
 *      + 10 道烙饼 + 20 道砂锅炖菜 + 10 道饺子馅 + 15 道炒饭），
 * 重复的菜名合并做法细节后去重，共 322 道。
 * 成品图存 public/recipes/<id>.jpg，与原文配图按菜序一一对应；原文无配图的菜 image 为空串，降级展示 emoji。
 * 其中 8 道补图来自 Wikimedia Commons / Pexels 的 CC 授权照片（详见 docs/菜谱配图来源.md），
 * 未找到真实对应图源的 26 道仍保留 image: ''，不做「近似图凑数」以免张冠李戴。
 *
 * 安全字段是本模块的重点：每道菜给出「有毒 / 无毒」结论、具体毒理与处理要求、
 * 常见过敏原。做法与注意事项在原文基础上做了细化补充，仅为家庭烹饪参考。
 */
/** 原「鱼虾豆腐」合篇按主料拆为四类；分类名会直接显示在卡片与详情弹框上 */
export type RecipeCategory =
  | '家常荤菜'
  | '猪肉做法'
  | '牛肉做法'
  | '羊肉做法'
  | '禽类做法'
  | '蛋类做法'
  | '下饭小炒'
  | '白菜做法'
  | '鱼类做法'
  | '虾类做法'
  | '其他海鲜'
  | '豆腐做法'
  | '家常素菜'
  | '砂锅做法'
  | '饺子做法'
  | '炒饭做法'
  | '凉菜主食'
export type SafetyLevel = 'safe' | 'caution' | 'danger'

export interface Recipe {
  id: string
  name: string
  category: RecipeCategory
  emoji: string
  /** 成品图（由 id 派生，见 RECIPES） */
  image: string
  time: string
  difficulty: '简单' | '中等' | '进阶'
  intro: string
  /** 主料 */
  ingredients: string[]
  /** 调料 / 腌料 / 碗汁 */
  seasonings: string[]
  steps: string[]
  tips: string[]
  safety: {
    level: SafetyLevel
    /** 有毒 / 无毒结论 */
    toxicity: string
    /** 毒理、风险点与处理要求 */
    hazards: string[]
  }
  allergens: string[]
  source: string
}

export const RECIPE_SERVINGS = '2~3 人一盘（1 大勺≈15ml，1 小勺≈5ml，1 小撮≈拇指食指捏起）'

export const SAFETY_LABEL: Record<SafetyLevel, string> = {
  safe: '常规安全',
  caution: '需彻底加热',
  danger: '高风险食材'
}

export const SAFETY_HINT: Record<SafetyLevel, string> = {
  safe: '食材本身无毒，按常规清洗与加热即可。',
  caution: '食材本身无毒，但生品可能带致病菌，必须彻底熟制。',
  danger: '生品或处理不当会产生毒素，务必按注意事项操作。'
}

